import sailpoint.connector.DelimitedFileConnector;
	import java.text.SimpleDateFormat;
  import java.time.*;
  import java.util.*;
	 map = DelimitedFileConnector.defaultBuildMap(cols, record);

  String endDate= map.get("endDate");
  if(endDate==null)
  {
  	map.put("IIQDisabled",false);
  }
  else
  {
      SimpleDateFormat sourceFormat = new SimpleDateFormat("dd-MM-yyyy"); 
      Date end_date = sourceFormat.parse(endDate);
      // getting current date
      LocalDate currentDate= LocalDate.now();
			SimpleDateFormat sourceFormat1 = new SimpleDateFormat("yyyy-MM-dd");
      Date today= sourceFormat1.parse(currentDate.toString());
     //System.out.println("## end date"+end_date +"  ## Today"+today );
      if(end_date.before(today))  // date expired
      {
				map.put("IIQDisabled",true);
      }
    else
      map.put("IIQDisabled",false);
  }

  return map;
